20	import { cache } from 'react';
21	import { after } from 'next/server';
22	import { getSession, requireSession, type AuthRuntime, type ResolvedSession } from '@paigasus/auth/server';
23	import type { Discovery } from '@paigasus/discovery/server';
24	import type { ConsoleCoreConfig } from './config-shape';
25	import type { ConsoleLogger } from './logger';
26	import { sessionExpired, type IamResult } from './errors';
27	import { createIamClients, type IamClients } from './iam-clients';
28	import { requestCorrelationId } from './correlation';
29	import { introspectWithProvisioning, type Principal } from './principal';
30	import { createMayI, type MayI } from './authorize';
31	import { cedarCapabilityOf, loadMyScopes, type MyScopes } from './scopes';
32	import { createAppDiscovery } from './discovery';
