34	export type ConsoleRuntime = {
35	  currentSession: () => Promise<ResolvedSession>;
36	  optionalSession: () => Promise<ResolvedSession | null>;
37	  sessionToken: () => Promise<string>;
38	  iamClients: () => Promise<IamClients>;
39	  iamClientsForAction: () => Promise<IamResult<IamClients>>;
40	  iamClientsForToken: (token: string, correlationId?: string | null) => IamClients;
41	  currentPrincipal: () => Promise<IamResult<Principal>>;
42	  mayI: () => Promise<MayI>;
43	  myScopes: () => Promise<IamResult<MyScopes>>;
44	  discovery: () => Discovery;
45	};
