47	export function createConsoleRuntime(deps: { config: () => ConsoleCoreConfig; authRuntime: () => Promise<AuthRuntime>; logger: ConsoleLogger }): ConsoleRuntime {
48	  /**
49	   * The clients for a token the caller already holds, over the app's configured IAM gRPC address.
50	   * No session lookup — used by `iamClients`/`iamClientsForAction` below and by the login
51	   * callback's resolver factory (the app's `lib/auth.ts`). NOT a `cache()`: it is parameterized by
52	   * `token`, and every call site already runs behind its own per-request memoization.
53	   */
54	  const iamClientsForToken = (token: string, correlationId: string | null = null): IamClients => createIamClients({ baseUrl: deps.config().PAIGASUS_IAM_GRPC_URL, token, correlationId });
