56	  /** The session for this request. Redirects to login when there is none. PAGE RENDERS ONLY. */
57	  const currentSession: () => Promise<ResolvedSession> = cache(async () => requireSession(await deps.authRuntime()));
58	
59	  /** The session for this request, WITHOUT a redirect. `null` when there is none. */
60	  const optionalSession: () => Promise<ResolvedSession | null> = cache(async () => getSession(await deps.authRuntime()));
61	
62	  /** The five IAM clients for this request, bound to the session's access token and correlation id. */
63	  const iamClients: () => Promise<IamClients> = cache(async () => {
64	    const session = await currentSession();
65	    return iamClientsForToken(session.accessToken, await requestCorrelationId());
66	  });
67	
68	  /** The session's access token — the bearer that @paigasus/discovery probes with. */
69	  const sessionToken: () => Promise<string> = cache(async () => (await currentSession()).accessToken);
70	
71	  /**
72	   * The five IAM clients for a SERVER ACTION. Deliberately NOT a `cache()`: it returns a `relogin`
73	   * failure rather than redirecting, so a Server Action can render an inline error.
74	   *
75	   * WHY AN ACTION MUST NOT REDIRECT HERE. `requireSession()` redirects basePath-RELATIVE, which a
76	   * page render needs, because Next's app render adds the basePath itself. A Server Action takes a
77	   * different path through Next: `next/dist/server/app-render/action-handler.js:261` writes the RAW
78	   * url into the `x-action-redirect` header, and `:906` writes the RAW url into `Location` for a
79	   * no-JS post. Only the internal RSC pre-fetch at `:267` adds the basePath. The browser then
80	   * resolves the raw value against the current URL and hard-navigates, so a user whose session
81	   * expired before pressing "Create" would land on `https://<host>/auth/login`, OUTSIDE the `/iam`
82	   * zone, where nothing serves a login route.
83	   *
84	   * The failure this returns carries `presentation: 'relogin'`, so `FormError` renders the
85	   * `SignInAgain` link, which builds `${basePath}${pathname}` itself and stays in the zone (spec
86	   * § 6.4: relogin is a link, never an automatic redirect).
87	   *
