100	
101	  /** One MayI per request, so the memo lives exactly one request. */
102	  const mayI: () => Promise<MayI> = cache(async () => {
103	    const [principal, clients] = await Promise.all([currentPrincipal(), iamClients()]);
104	    return createMayI({ authz: clients.authz, principalPrn: principal.ok ? principal.value.prn : null, logger: deps.logger });
105	  });
106	
107	  /** One handle per request; background revalidation runs after the response, through after(). */
108	  const discovery: () => Discovery = cache(() => createAppDiscovery({ config: deps.config(), log: deps.logger, waitUntil: (p) => after(p) }));
109	
110	  /** One per request. The page and the switcher share it (spec § 5.1). */
111	  const myScopes: () => Promise<IamResult<MyScopes>> = cache(async () => {
112	    const principal = await currentPrincipal();
