// SPDX-License-Identifier: Apache-2.0
//
// The package's one entry. Server-only: every module it re-exports imports 'server-only', so a
// client component that reaches this package fails the build loudly rather than shipping a
// token-bearing module into a browser bundle.
import 'server-only';

export { principalPrnOf } from './principal-prn';
export { ROOT_PRN, isUuid, organizationPrn, parseTenancyPrn, projectPrn, teamPrn, type TenancyKind, type TenancyRef } from './prn-tenancy';
export { CORRELATION_HEADER, REQUEST_PATH_HEADER } from './correlation-header';
export { createJsonLogger, logger, type AppEventFields, type AppEventName, type ConsoleLogger } from './logger';
export { callIam, neverReachedIam, sessionExpired, type ActionState, type IamResult } from './errors';
export { FORBIDDEN_VIEW_CORRELATION, requestCorrelationId, requestPath } from './correlation';
export { createIamClients, type IamClients } from './iam-clients';
export { createIntrospectPrincipalResolver } from './principal-resolver';
export { createConsoleRuntime, type ConsoleRuntime } from './runtime';

export { introspectWithProvisioning, type Principal } from './principal';
export { createMayI, type IamAction, type MayI } from './authorize';
export { SCOPE_CAP, cedarCapabilityOf, loadMyScopes, switcherOrgs, type MyScopes, type ScopeEntry } from './scopes';
export { createAppDiscovery, descriptorCacheFor, resetDiscoveryForTest } from './discovery';

// SPDX-License-Identifier: Apache-2.0
//
// The testing surface. OUTSIDE src/ and deliberately NOT server-only guarded: vitest and Playwright
// harnesses import it outside a Next server. That placement is what lets the src/ rule — every file
// imports 'server-only' — hold with no exception.
export {
  denial,
  errorInfoOf,
  FAKE_IAM_ISSUER,
  IAM_ERROR_DOMAIN,
  startFakeIam,
  type FakeIam,
  type FakeIamCall,
  type FakeIamContext,
  type FakeIamHandlers,
  type FakeIamMethod,
  type ServiceDescriptorBody,
} from './fake-iam';
export { startFakeIdp, type FakeIdp } from './fake-idp';
export { testTls, type TlsMaterial } from './tls';
export { startTlsTerminator } from './tls-terminator';

{
  "name": "@paigasus/console-core",
  "_comment_exports": "A root export plus a testing subpath. Root is server-only, the way @paigasus/sdk's is — @paigasus/auth and @paigasus/discovery omit a root export only because they also have a CLIENT surface, which this package does not. ./testing is deliberately outside src/ and carries no server-only guard: vitest and Playwright harnesses import it outside a Next server.",
  "version": "0.0.0",
  "private": true,
  "type": "module",
  "engines": {
    "node": ">=24"
  },
  "license": "Apache-2.0",
  "description": "Server-only console composition shared by the Paigasus zones: IAM clients, provisioning and the principal resolver, authorization self-queries, scopes, discovery, the error wrapper and the JSON-lines logger.",
  "exports": {
    ".": "./src/index.ts",
    "./testing": "./testing/index.ts"
  },
  "scripts": {
    "typecheck": "tsc -p tsconfig.json --noEmit"
  },
  "dependencies": {
    "@bufbuild/protobuf": "catalog:",
    "@connectrpc/connect": "catalog:",
    "@paigasus/auth": "workspace:*",
    "@paigasus/discovery": "workspace:*",
    "@paigasus/sdk": "workspace:*",
    "redis": "catalog:",
    "server-only": "catalog:"
  },
  "peerDependencies": {
    "next": "catalog:",
    "react": "catalog:"
  },
  "devDependencies": {
    "@connectrpc/connect-node": "catalog:",
    "@paigasus/proto": "workspace:*",
    "@types/node": "catalog:",
    "@types/react": "catalog:",
    "jose": "catalog:",
    "msw": "catalog:",
    "next": "catalog:",
    "react": "catalog:",
    "testcontainers": "catalog:",
    "typescript": "catalog:",
    "vitest": "catalog:"
  }
}

// SPDX-License-Identifier: Apache-2.0
//
// The ONE reading of IAM's `principal_prn` (review, defect 1).
//
// THE DRIFT THIS CLOSES. Introspect answers a proto3 string, and an unset string arrives as `''`.
// Two call sites map that answer and they disagreed: the login resolver (lib/principal-resolver.ts)
// normalised `'' -> null`, while the LIVE path (lib/principal.ts, which every page uses) passed the
// empty string through. An empty PRN then slipped past every `=== null` guard downstream: mayI()
// asked IAM `isAuthorized({ principalPrn: '' })`, IAM refused with InvalidArgument, mayI() failed
// open, and EVERY mutation control rendered for a principal IAM could not name — while myScopes()
// lost its grants to a listRoleGrants('') that failed for the same reason. Both paths read the
// field here now, so they cannot disagree about what an unnamed principal looks like again.
import 'server-only';

/**
 * IAM's principal PRN, or `null` when IAM named no principal. The value is returned VERBATIM when
 * it is a name at all: only this module decides what "no name" means, never what a name looks like
 * — IAM parses the PRN, and the console does not second-guess its grammar (spec § 6.1). Whitespace
 * alone is not a name either, so it reads as `null` rather than reaching IAM as a PRN.
 */
export function principalPrnOf(raw: string): string | null {
  return raw.trim() === '' ? null : raw;
}

