1	// SPDX-License-Identifier: Apache-2.0
2	//
3	// @paigasus/auth's PrincipalResolver port, implemented over IAM (spec § 4.5). The login callback
4	// calls it once (ts/packages/paigasus-auth/src/http/routes.ts:236), with the new access token.
5	//
6	// It lives in the APP because @paigasus/auth must not import @paigasus/sdk
7	// (ts/packages/paigasus-auth/src/ports/principal-resolver.ts:3-8), and the sdk boundary rule bans
8	// every @paigasus/* import except proto. SMA-631 records a shared home for SMA-512.
9	//
10	// IT NEVER FAILS THE LOGIN. On any failure it returns principalPrn: null, empty lists and
11	// grantsAvailable: false. An IAM answer that is a failure logs `principal.resolve_failed`; a
12	// thrown error — a bug in this function, not an IAM answer — logs `principal.resolve_crashed`
13	// instead, so the two causes stay distinguishable in the log. The pages do not read this snapshot
14	// (they call currentPrincipal()), so a degraded login costs nothing after the first render.
15	import 'server-only';
16	import type { PrincipalResolver, ResolvedPrincipal } from '@paigasus/auth/server';
17	import { principalPrnOf } from './principal-prn';
18	import type { ConsoleLogger } from './logger';
19	import { callIam } from './errors';
20	import type { IamClients } from './iam-clients';
21	
22	/** The user waits on the login callback, so each call gets 3 s, not the SDK's 10 s (transport.ts:42). */
23	const DEFAULT_TIMEOUT_MS = 3_000;
24	
25	export function createIntrospectPrincipalResolver(deps: {
26	  /**
27	   * May be async: lib/auth.ts reads the request's correlation id here, so the login callback's IAM
28	   * calls join the id proxy.ts minted. A factory that throws — or a promise that rejects — is a bug,
29	   * not an IAM answer, so it lands in the `resolve_crashed` catch below like any other throw.
30	   */
31	  clientsForToken: (token: string) => Pick<IamClients, 'authn' | 'serviceInfo'> | Promise<Pick<IamClients, 'authn' | 'serviceInfo'>>;
32	  logger: ConsoleLogger;
33	  timeoutMs?: number;
34	}): PrincipalResolver {
35	  const timeoutMs = deps.timeoutMs ?? DEFAULT_TIMEOUT_MS;
36	
37	  return {
38	    async resolve({ accessToken, idTokenClaims }): Promise<ResolvedPrincipal> {
39	      const degradedPrincipal = (): ResolvedPrincipal => ({
40	        principalPrn: null,
41	        issuer: idTokenClaims.iss,
42	        subject: idTokenClaims.sub,
43	        memberships: [],
44	        roleGrants: [],
45	        grantsAvailable: false,
46	      });
47	      const degraded = (presentation: string): ResolvedPrincipal => {
48	        deps.logger.appEvent('principal.resolve_failed', { presentation });
49	        return degradedPrincipal();
50	      };
51	      // The try is broad ON PURPOSE (spec § 4.5): it wraps the two calls AND the response mapping.
52	      // By the time this runs, the login callback has already spent the single-use OIDC code, so a
53	      // throw here would strand the user with no way to retry — a degraded login is the right
54	      // outcome whether IAM refused or this function has a bug. The two causes still need to read
55	      // apart in the log, so they use different events: a `callIam` result of `ok: false` is an IAM
56	      // ANSWER and logs `principal.resolve_failed` with its presentation, from inside the try below.
57	      // Anything that instead THROWS out of the try — a bug, not an IAM answer — is caught here and
58	      // logs `principal.resolve_crashed`, so an operator can tell a console bug from an IAM outage.
59	      try {
60	        const clients = await deps.clientsForToken(accessToken);
61	        // 1. The provisioning call, with the NEW token as the bearer.
62	        const provisioned = await callIam(() => clients.serviceInfo.getServiceInfo({}, { timeoutMs }));
63	        if (!provisioned.ok) return degraded(provisioned.error.presentation);
64	        // 2. Introspect reads the token from the REQUEST field (authn.rs:59), not from the header.
65	        const answer = await callIam(() => clients.authn.introspect({ token: accessToken }, { timeoutMs }));
66	        if (!answer.ok) return degraded(answer.error.presentation);
67	        const me = answer.value;
68	        // 3. IAM reports no role grants here (authenticate_token.rs:161-165), and the port says
69	        //    to treat that as UNKNOWN (ports/principal-resolver.ts:32-36).
70	        return {
71	          // The SAME reading as the live path (lib/principal-prn.ts). The two used to disagree.
72	          principalPrn: principalPrnOf(me.principalPrn),
73	          issuer: me.issuer,
74	          subject: me.subject,
75	          memberships: me.memberships.map((m) => ({ id: m.id, principalPrn: m.principalPrn, nodePrn: m.nodePrn })),
76	          roleGrants: [],
77	          grantsAvailable: false,
78	        };
79	      } catch (err) {
80	        // callIam rethrows everything that is not a ConnectError, and a bug in the mapping above
81	        // throws too. Neither is an IAM answer, so neither is `principal.resolve_failed`. No token,
82	        // DSN or cookie is logged here — only the error's own shape.
83	        const name = err instanceof Error ? err.constructor.name : typeof err;
84	        const message = err instanceof Error ? err.message : String(err);
85	        deps.logger.appEvent('principal.resolve_crashed', { name, message });
86	        return degradedPrincipal();
87	      }
88	    },
89	  };
90	}
91

